        $status=self::defaultStatus();
        foreach ($rows as $row) {
            $key=substr((string)$row['setting_key'],strlen(self::SETTING_PREFIX));
            if (array_key_exists($key,$status)) $status[$key]=(string)$row['setting_value'];
        }
